package uk.ac.ravensbourne.casevault.security;

import io.github.bucket4j.Bandwidth; import io.github.bucket4j.Bucket; import io.github.bucket4j.ConsumptionProbe; import java.time.Duration; import java.util.concurrent.*; import org.springframework.stereotype.Service; import uk.ac.ravensbourne.casevault.audit.AuditEventType; import uk.ac.ravensbourne.casevault.audit.AuditService; import uk.ac.ravensbourne.casevault.common.TestOnly;
/** Limits credential guessing by IP and account before password verification (CWE-307). */
@Service public class LoginRateLimiter { private final ConcurrentMap<String,Bucket> buckets=new ConcurrentHashMap<>(); private final ConcurrentMap<String,Bucket> denialAuditBuckets=new ConcurrentHashMap<>(); private final AuditService audit; public LoginRateLimiter(AuditService audit){this.audit=audit;} public boolean allow(String ip,String account){return consume(ip,account).allowed();} public Decision consume(String ip,String account){String safeIp=normaliseIp(ip);ConsumptionProbe ipProbe=bucket("ip:"+safeIp,30).tryConsumeAndReturnRemaining(1);ConsumptionProbe accountProbe=bucket("account:"+normaliseAccount(account),10).tryConsumeAndReturnRemaining(1);if(ipProbe.isConsumed()&&accountProbe.isConsumed())return new Decision(true,0);if(denialAuditBuckets.computeIfAbsent("login:"+safeIp,k->newBucket(1)).tryConsume(1))audit.record(null,AuditEventType.RATE_LIMITED,"AUTH",null,"login-rate-limited");long wait=Math.max(ipProbe.isConsumed()?0:ipProbe.getNanosToWaitForRefill(),accountProbe.isConsumed()?0:accountProbe.getNanosToWaitForRefill());return new Decision(false,Math.max(1,(wait+999_999_999L)/1_000_000_000L));} @TestOnly public void reset(){buckets.clear();denialAuditBuckets.clear();} private Bucket bucket(String key,int capacity){return buckets.computeIfAbsent(key,k->newBucket(capacity));} private Bucket newBucket(int capacity){return Bucket.builder().addLimit(Bandwidth.builder().capacity(capacity).refillGreedy(capacity,Duration.ofMinutes(1)).build()).build();} private String normaliseIp(String ip){return ip==null||ip.isBlank()?"unknown":ip.replaceAll("[\\r\\n]","");} private String normaliseAccount(String account){return account==null?"unknown":account.toLowerCase().replaceAll("[\\r\\n]","");} public record Decision(boolean allowed,long retryAfterSeconds){} }
